export const metrics={temperature:['Temperature','°C','environment'],humidity:['Humidity','% RH','environment'],pressure:['Pressure','hPa','environment'],voltage:['Voltage','V','power'],current:['Current','A','power'],power:['Power','W','power'],ax:['Acceleration X','m/s²','motion'],ay:['Acceleration Y','m/s²','motion'],az:['Acceleration Z','m/s²','motion'],gx:['Gyroscope X','°/s','motion'],gy:['Gyroscope Y','°/s','motion'],gz:['Gyroscope Z','°/s','motion']};
export const sensors=[['BMP280','Temperature & pressure',['temperature','pressure']],['DHT22','Temperature & humidity',['temperature','humidity']],['MPU6050 #1','Primary motion sensing',['ax','ay','az','gx','gy','gz']],['MPU6050 #2','Secondary motion sensing',['ax','ay','az','gx','gy','gz']],['INA219','Power monitoring',['voltage','current','power']]];
export const scenarios=['Normal operation','Warning','Critical event','Sensor failure','Communication loss','Recovery'];
export class SimulationService{
 constructor(){this.scenario='Normal operation';this.sequence=1800;this.listeners=new Set();this.events=[];this.logs=[];this.history=[];this.interval=2000;this.last=Date.now();this.started=this.last;for(let i=720;i>0;i--)this.history.push(this.packet(this.last-i*120000,i));this.current=this.packet(this.last,0);this.history.push(this.current);this.log('SYSTEM','INFO','Simulation provider initialized. ATLAS-001 is ready.');this.timer=setInterval(()=>this.tick(),this.interval)}
 packet(t,i=0){let phase=t/65000;let v=5.04+Math.sin(phase*.32)*.035,c=.236+Math.sin(phase*.9)*.012;const warning=this.scenario==='Warning';let vals={temperature:26.4+Math.sin(phase)*.45+(warning?6:0),humidity:48.2+Math.cos(phase*.6)*1.8,pressure:1013.2+Math.sin(phase*.18)*.8,voltage:v,current:c,power:v*c,ax:Math.sin(phase*2)*.12,ay:Math.cos(phase*1.7)*.09,az:9.81+Math.sin(phase)*.025,gx:Math.sin(phase)*.3,gy:Math.cos(phase)*.2,gz:Math.sin(phase*.7)*.15};const readings={};for(const [k,value]of Object.entries(vals))readings[k]={value:this.scenario==='Sensor failure'&&k==='humidity'?null:value,unit:metrics[k][1],timestamp:t,quality:this.scenario==='Sensor failure'&&k==='humidity'?'UNAVAILABLE':'VALID',source:'SIMULATION'};return {deviceId:'ATLAS-001',timestamp:t,sequence:this.sequence-i,mode:'SIMULATION',readings,environment:Object.fromEntries(Object.keys(readings).filter(k=>metrics[k][2]==='environment').map(k=>[k,readings[k]])),motion:{accelerometer:{x:readings.ax,y:readings.ay,z:readings.az},gyroscope:{x:readings.gx,y:readings.gy,z:readings.gz}},power:{voltage:readings.voltage,current:readings.current,power:readings.power},communication:{state:'CONNECTED',lastPacket:t}}}
 subscribe(fn){this.listeners.add(fn);return()=>this.listeners.delete(fn)}emit(){this.listeners.forEach(fn=>fn(this.current))}
 tick(){if(this.scenario!=='Communication loss'){this.sequence++;this.last=Date.now();this.current=this.packet(this.last);this.history.push(this.current);if(this.history.length>2500)this.history.shift()}this.emit()}
 health(){const age=Date.now()-this.last;return age>12000?'OFFLINE':age>6000?'STALE':this.scenario==='Critical event'?'CRITICAL':this.scenario==='Recovery'?'RECOVERING':['Warning','Sensor failure'].includes(this.scenario)?'WARNING':'NORMAL'}
 reading(k){const r=this.current.readings[k];return {...r,quality:Date.now()-r.timestamp>6000&&r.quality==='VALID'?'STALE':r.quality}}
 setScenario(s){if(!scenarios.includes(s))throw Error('Unknown scenario');clearTimeout(this.recovery);this.scenario=s;const severity=s==='Critical event'?'CRITICAL':['Warning','Sensor failure','Communication loss'].includes(s)?'WARNING':'INFO';if(['Recovery','Normal operation'].includes(s))this.events.forEach(e=>e.state='RESOLVED');const descriptions={'Normal operation':'All subsystems operating normally.','Warning':'Simulated environmental warning. Demonstration condition; not a calibrated threshold.','Critical event':'Simulated controller fault detected.','Sensor failure':'DHT22 humidity reading unavailable.','Communication loss':'LoRa telemetry interrupted. Freshness will degrade after 6 seconds and go offline after 12 seconds.','Recovery':'Communication restored. Subsystems are recovering.'};this.events.unshift({id:'EVT-'+String(this.events.length+1).padStart(4,'0'),timestamp:Date.now(),device:'ATLAS-001',type:s,subsystem:s.includes('Communication')?'LoRa':s.includes('Sensor')?'Environment':'System',severity,state:s==='Normal operation'?'RESOLVED':'ACTIVE',description:descriptions[s]});this.log('SIMULATION',severity==='CRITICAL'?'ERROR':severity,descriptions[s]);this.tick();if(s==='Recovery')this.recovery=setTimeout(()=>this.setScenario('Normal operation'),5000)}
 acknowledge(id){const e=this.events.find(e=>e.id===id);if(e&&e.state==='ACTIVE'){e.state='ACKNOWLEDGED';this.log('EVENT ENGINE','INFO',id+' acknowledged');this.emit()}}
 log(source,level,message){this.logs.unshift({timestamp:Date.now(),source,level,message});this.logs=this.logs.slice(0,200)}
 setRefresh(ms){this.interval=ms;clearInterval(this.timer);this.timer=setInterval(()=>this.tick(),ms);this.emit()}
}
export const service=new SimulationService();
